import{_ as t,o,c as a,a2 as r}from"./chunks/framework.Bg-Zxr5O.js";const _=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/Matrix-Exponentiation-Operator.md","filePath":"manual-en/Matrix-Exponentiation-Operator.md","lastUpdated":1785684581000}'),i={name:"manual-en/Matrix-Exponentiation-Operator.md"};function d(n,e,c,s,p,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h4 id="_16-4-1-7-matrix-exponentiation-operator" tabindex="-1">16.4.1.7 Matrix Exponentiation Operator <code>**</code> <a class="header-anchor" href="#_16-4-1-7-matrix-exponentiation-operator" aria-label="Permalink to &quot;16.4.1.7 Matrix Exponentiation Operator `**`&quot;">​</a></h4><p>The result of <code>A**B</code> is defined as follows when <code>A</code> is a square matrix and <code>B</code> is an integer scalar:</p><ul><li>For <code>B &gt; 0</code>, <code>A**B</code> is <code>A*…*A</code>, where there are <code>B</code> ‘A’s. (PSPP implements this efficiently for large <code>B</code>, using exponentiation by squaring.)</li><li>For <code>B &lt; 0</code>, <code>A**B</code> is <code>INV(A**(-B))</code>.</li><li>For <code>B = 0</code>, <code>A**B</code> is the identity matrix.</li></ul><p>PSPP reports an error if <code>A</code> is not square or <code>B</code> is not an integer.</p><p>Examples:</p><table tabindex="0"><thead><tr><th>{2, 5; 1, 4}**3</th><th>⇒</th><th>{48, 165; 33, 114}</th></tr></thead><tbody><tr><td>{2, 5; 1, 4}**0</td><td>⇒</td><td>{1, 0; 0, 1}</td></tr><tr><td>10*{4, 7; 2, 6}**-1</td><td>⇒</td><td>{6, -7; -2, 4}</td></tr></tbody></table>',6)])])}const h=t(i,[["render",d]]);export{_ as __pageData,h as default};
